			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; proj.bas 3: r = Vector3D.AddPoint(128, 0, 0) : r = Vector3D.AddPoint(0, 128, 0) : r = Vector3D.AddPoint(0, 0, 128) : r = Vector3D.AddPoint(-128, -128, 0)
